const candidateSkin = process.env.MX_TEST_SKIN || 'style2';
const{chromium}=require(process.env.MX_PLAYWRIGHT_MODULE||'playwright-core');const fs=require('node:fs');const out=process.env.MX_OUTPUT_DIR||'docs/styles/'+candidateSkin+'/implementation/round1';fs.mkdirSync(out,{recursive:true});(async()=>{const b=await chromium.launch({executablePath:process.env.MX_CHROME||'/Applications/Google Chrome.app/Contents/MacOS/Google Chrome',headless:true});const p=await b.newPage({viewport:{width:1000,height:1100}});const errors=[],failures=[];p.on('pageerror',e=>errors.push(String(e)));p.on('requestfailed',r=>failures.push({url:r.url(),error:r.failure()?.errorText}));await p.goto(process.env.MX_PRODUCTION_URL||'http://127.0.0.1:5184');await p.locator('#enter').click();await p.locator('.mx-table').waitFor({timeout:60000});await p.waitForTimeout(400);const state=await p.locator('.mx-game').evaluate(e=>({skin:e.dataset.skin,layout:e.querySelector('.mx-table').dataset.tableLayout,seats:e.querySelectorAll('.mx-seat').length,background:getComputedStyle(e.querySelector('.mx-table')).backgroundImage,nav:e.querySelectorAll('.mx-nav-button').length}));const artwork=await p.evaluate(async()=>{const table=document.querySelector('.mx-table'),icon=document.querySelector('.mx-nav-icon');const images=[getComputedStyle(table).backgroundImage,getComputedStyle(icon).backgroundImage];return await Promise.all(images.map(async url=>{const src=url.match(/url\(["']?(.*?)["']?\)/)?.[1];if(!src)return {url,loaded:false};const image=new Image();image.src=src;try{await image.decode();return {url:src,loaded:true,width:image.naturalWidth,height:image.naturalHeight}}catch{return {url:src,loaded:false}}}))});await p.locator('#game').screenshot({path:out+'/production.png'});const actionBounds=await p.locator('.mx-game').evaluate(e=>{const root=e.getBoundingClientRect(),a=e.querySelector('.mx-operation-row').getBoundingClientRect();return {top:a.top-root.top,bottom:a.bottom-root.top,height:root.height,inside:a.top>=root.top&&a.bottom<=root.bottom+1,nearBottom:a.top-root.top>root.height*.7}});const hostExports=await p.evaluate(async(skin)=>{const api=await import('/client/mx-game.js');return {style1:typeof api.style1?.createClient,style2:typeof api.style2?.createClient,selected:typeof api[skin]?.createClient,mountMxGame:typeof api.mountMxGame}},candidateSkin);const result={state,actionBounds,hostExports,artwork,errors,failures,pass:Object.values(hostExports).every(v=>v==='function')&&state.skin===candidateSkin&&state.layout==='balanced'&&state.seats>0&&actionBounds.inside&&actionBounds.nearBottom&&artwork.every(x=>x.loaded)&&!errors.length};fs.writeFileSync(out+'/production.json',JSON.stringify(result,null,2));await p.locator('#preview-mode').selectOption('portrait');await p.waitForTimeout(100);await p.locator('#game').screenshot({path:out+'/production-portrait.png'});console.log(result);if(!result.pass)process.exitCode=1;await b.close()})();
